type AssessmentAnswers = { fullName: string; countryResidence: string; preferredDestination: string; immigrationGoal: string; currentRole: string; experienceRange: string; achievement: string };
const emptyAnswers: AssessmentAnswers = { fullName: "", countryResidence: "", preferredDestination: "", immigrationGoal: "", currentRole: "", experienceRange: "", achievement: "" };

function Assessment({ onApplicationChanged, onBookCall }: { onApplicationChanged?: () => Promise<void>; onBookCall?: () => void }) {
  const [section, setSection] = useState(1); const [answers, setAnswers] = useState<AssessmentAnswers>(emptyAnswers); const [message, setMessage] = useState("Loading your saved assessment…"); const [busy, setBusy] = useState(false); const [applicationStatus, setApplicationStatus] = useState<"loading" | "draft" | "submitted">("loading"); const [reviewStatus, setReviewStatus] = useState("draft"); const [submittedAt, setSubmittedAt] = useState<number | null>(null); const [publicId, setPublicId] = useState(""); const sectionData = [{ title: "About you", copy: "Confirm the personal details and destination that help us understand your circumstances and timing." }, { title: "Career & evidence", copy: "Tell us what you have done, how your work mattered and what can verify it." }, { title: "Review your answers", copy: "Check your information before submitting it to the Migrz assessment team." }, { title: "Submit assessment", copy: "Submit your completed record for professional review." }];
  useEffect(() => { void (async () => { const response = await fetch("/api/portal/application", { cache: "no-store" }); const data = await response.json() as { application?: { currentSection?: number; answers?: Partial<AssessmentAnswers>; status?: string; reviewStatus?: string; submittedAt?: number | null; publicId?: string } }; if (response.ok && data.application) { setSection(Math.min(4, data.application.currentSection || 1)); setAnswers({ ...emptyAnswers, ...data.application.answers }); setApplicationStatus(data.application.status === "submitted" ? "submitted" : "draft"); setReviewStatus(data.application.reviewStatus || data.application.status || "draft"); setSubmittedAt(data.application.submittedAt || null); setPublicId(data.application.publicId || ""); setMessage(data.application.status === "submitted" ? "Assessment submitted." : "All changes are stored securely."); } else { setApplicationStatus("draft"); setMessage("Start with the questions below."); } })(); }, []);
  const update = (field: keyof AssessmentAnswers, value: string) => setAnswers((current) => ({ ...current, [field]: value }));
  const save = async (nextSection: number) => { setBusy(true); setMessage("Saving…"); const response = await fetch("/api/portal/application", { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ currentSection: nextSection, answers }) }); const data = await response.json() as { error?: string }; setBusy(false); if (!response.ok) return setMessage(data.error || "Unable to save."); setMessage("All changes saved."); setSection(nextSection); };
  const submit = async () => { setBusy(true); setMessage("Submitting…"); const saved = await fetch("/api/portal/application", { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ currentSection: 4, answers }) }); if (!saved.ok) { const data = await saved.json() as { error?: string }; setBusy(false); return setMessage(data.error || "Unable to save."); } const response = await fetch("/api/portal/application", { method: "POST" }); const data = await response.json() as { error?: string; submittedAt?: number; publicId?: string }; setBusy(false); if (!response.ok) return setMessage(data.error || "Unable to submit."); setSubmittedAt(data.submittedAt || Date.now()); setPublicId(data.publicId || publicId); setReviewStatus("submitted"); setApplicationStatus("submitted"); setMessage("Assessment submitted to Migrz."); if (onApplicationChanged) void onApplicationChanged(); };
  if (applicationStatus === "submitted") return <div className="portal-subpage portal-submitted"><header><span className="portal-eyebrow">{reviewStatus === "completed" ? "Review completed" : "Assessment received"}</span><h1>{reviewStatus === "completed" ? "Your assessment response is ready." : "Your assessment is with Migrz."}</h1><p>{reviewStatus === "completed" ? "Your review is complete. Request a private call to discuss the assessment findings, questions and recommended next steps." : "Your answers are locked and safely submitted. The Migrz team can now review your professional record and supporting evidence."}</p>{reviewStatus === "completed" && onBookCall && <button className="portal-primary" onClick={onBookCall}>Book your review call <Arrow /></button>}</header><section className="portal-submission-reference"><span>Submission ID</span><strong>{publicId || "Being assigned"}</strong><small>Keep this reference for any communication with the Migrz team.</small></section><section className="portal-submitted-card"><span className="portal-submitted-check" aria-hidden="true">✓</span><div><span className="portal-eyebrow">{reviewStatus === "completed" ? "Assessment response ready" : reviewStatus === "in_review" ? "Professional review in progress" : reviewStatus === "needs_information" ? "More information requested" : "Awaiting professional review"}</span><h2>{reviewStatus === "completed" ? "Review completed" : "Submission complete"}</h2><p>{reviewStatus === "completed" ? "You can now request a call of up to 60 minutes with Migrz. The team will confirm the final time and call details by email and in this portal." : reviewStatus === "needs_information" ? "The Migrz team needs additional information before completing the assessment. Check your registered email for the request." : "There is nothing else you need to submit here unless the team asks for clarification. You may continue adding relevant documents while your assessment is awaiting review."}</p>{submittedAt && <small>Received {new Date(submittedAt).toLocaleString([], { dateStyle: "medium", timeStyle: "short" })}</small>}</div><div className="portal-submitted-next"><strong>What happens next</strong><ol>{reviewStatus === "completed" ? <><li>Request a suitable time for your private call.</li><li>Migrz confirms the final time and call details.</li><li>Meet for up to 60 minutes to discuss the review and next steps.</li></> : <><li>Migrz reviews your answers and evidence.</li><li>The team compares supported destination pathways.</li><li>You receive the assessment response through your registered email.</li></>}</ol></div></section></div>;
  const current = sectionData[section - 1];
  return <div className="portal-subpage"><header><span className="portal-eyebrow">My assessment</span><h1>{current.title}</h1><p>{current.copy}</p></header><Journey /><div className="portal-form-layout"><aside><strong>Paid assessment</strong><p>Your draft is saved to your secure account.</p><div><i style={{ width: `${section * 25}%` }} /></div><small>Step {section} of 4</small></aside><form onSubmit={(event) => { event.preventDefault(); if (section === 4) void submit(); else void save(Math.min(4, section + 1)); }}>
    {section === 1 && <><label>Full legal name<input value={answers.fullName} onChange={(event) => update("fullName", event.target.value)} placeholder="As shown on your passport" required /></label><label>Current country of residence<input value={answers.countryResidence} onChange={(event) => update("countryResidence", event.target.value)} placeholder="Where you currently live" required /></label><label>Preferred destination<select value={answers.preferredDestination} onChange={(event) => update("preferredDestination", event.target.value)} required><option value="" disabled>Select a supported country</option>{supportedDestinations.map((country) => <option key={country} value={country}>{country}</option>)}</select><small>Migrz currently assesses pathways for these six destinations.</small></label><label className="portal-wide-field">Primary immigration goal<textarea value={answers.immigrationGoal} onChange={(event) => update("immigrationGoal", event.target.value)} placeholder="Tell us what you hope to achieve and why this destination matters to you." required /></label></>}
    {section === 2 && <><label>Current professional role<input value={answers.currentRole} onChange={(event) => update("currentRole", event.target.value)} placeholder="Role or title" required /></label><label>Years of relevant experience<select value={answers.experienceRange} onChange={(event) => update("experienceRange", event.target.value)} required><option value="" disabled>Select a range</option><option>Less than 3 years</option><option>3–5 years</option><option>6–10 years</option><option>More than 10 years</option></select></label><label>Most important professional achievement<textarea value={answers.achievement} onChange={(event) => update("achievement", event.target.value)} placeholder="What changed because of your work? Include measurable evidence where possible." required /></label></>}
    {section === 3 && <div className="portal-review-box"><strong>Review your professional record.</strong><p><b>{answers.fullName || "Name not added"}</b><br />{answers.currentRole || "Role not added"} · {answers.experienceRange || "Experience not added"}</p><p><b>Preferred destination:</b> {answers.preferredDestination || "Not selected"}</p><p>{answers.immigrationGoal || "Immigration goal not added"}</p><p>{answers.achievement || "Achievement not added"}</p><button type="button" onClick={() => setSection(1)}>Edit your answers</button></div>}
    {section === 4 && <div className="portal-review-box"><strong>Ready for professional review?</strong><p>Submitting sends your completed record to Migrz. You can still add documents before the assessment team begins its review.</p></div>}
    <footer><span aria-live="polite">{message}</span><button className="portal-primary" type="submit" disabled={busy}>{busy ? "Working…" : section === 4 ? "Submit assessment" : "Save & continue"}<Arrow /></button></footer>
  </form></div></div>;
}

type PortalAppointment = { id: string; publicId: string; status: string; requestedStart: number; durationMinutes: number; timezone: string; applicantNote: string; confirmedStart: number | null; meetingUrl: string | null; adminNote: string; provider: string; cancelUrl: string | null; rescheduleUrl: string | null; completedAt: number | null };
function Appointment({ reviewComplete, applicationPublicId, onViewNotifications }: { reviewComplete: boolean; applicationPublicId: string; onViewNotifications: () => void }) {
  const [appointment, setAppointment] = useState<PortalAppointment | null>(null); const [requestedStart, setRequestedStart] = useState(""); const [duration, setDuration] = useState(60); const [note, setNote] = useState(""); const [timezone] = useState(() => Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC"); const [message, setMessage] = useState("Loading appointment status…"); const [busy, setBusy] = useState(false); const [slots, setSlots] = useState<string[]>([]); const [liveBooking, setLiveBooking] = useState(false); const [availabilityLoaded, setAvailabilityLoaded] = useState(false);
  const [clock] = useState(() => Date.now());
  const load = useCallback(async () => { const response = await fetch("/api/portal/appointment", { cache: "no-store" }); const data = await response.json() as { appointment?: PortalAppointment | null; error?: string }; if (response.ok) { setAppointment(data.appointment || null); setMessage(data.appointment ? "Your appointment record is current." : "No review call has been requested yet."); } else setMessage(data.error || "Unable to load appointment status."); }, []);
  // Appointment state is private and resolved from the authenticated account.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { if (reviewComplete) void load(); else setMessage("Call booking unlocks after Migrz completes your review."); }, [load, reviewComplete]);
  // Availability is fetched once after the private appointment record resolves.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { if (!reviewComplete || appointment || availabilityLoaded) return; setAvailabilityLoaded(true); const start = new Date(clock + 3600000).toISOString(); const end = new Date(clock + 14 * 86400000).toISOString(); void fetch(`/api/portal/appointment/availability?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`, { cache: "no-store" }).then((response) => response.json()).then((data: { configured?: boolean; slots?: Array<{ startTime: string }> }) => { setLiveBooking(Boolean(data.configured)); setSlots((data.slots || []).map((slot) => slot.startTime)); }).catch(() => undefined); }, [appointment, availabilityLoaded, clock, reviewComplete]);
  const submitAppointment = async (bookingMode: "calendly" | "manual") => { setBusy(true); setMessage(bookingMode === "calendly" ? "Confirming your live booking…" : "Saving your call request…"); const response = await fetch("/api/portal/appointment", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ requestedStart: new Date(requestedStart).getTime(), durationMinutes: bookingMode === "calendly" ? 60 : duration, timezone, note, bookingMode }) }); const data = await response.json() as { appointment?: PortalAppointment; error?: string; bookingFallback?: boolean }; setBusy(false); if (!response.ok) { setMessage(data.error || "Unable to book the call."); return; } setAppointment(data.appointment || null); setMessage(data.bookingFallback ? "Calendly could not confirm instantly, so your selected time was sent to Migrz for confirmation." : bookingMode === "calendly" ? "Your review call is confirmed." : "Your call request has been sent to Migrz."); };
  const requestAppointment = async (event: React.FormEvent) => { event.preventDefault(); await submitAppointment(liveBooking ? "calendly" : "manual"); };
  if (!reviewComplete) return <div className="portal-subpage"><header><span className="portal-eyebrow">Review call</span><h1>Call booking is not available yet.</h1><p>Once the professional review is completed, this workspace will let you request a private call of up to 60 minutes.</p></header><section className="portal-appointment-lock"><strong>Current requirement</strong><p>Assessment review must be marked complete by Migrz.</p></section></div>;
  const callTime = appointment?.confirmedStart || appointment?.requestedStart; const closeToCall = Boolean(callTime && Math.abs(callTime - clock) <= 2 * 3600000); const completed = appointment?.status === "completed";
  return <div className="portal-subpage portal-appointment"><header><span className="portal-eyebrow">Review complete · {applicationPublicId}</span><h1>{completed ? "Your review call is complete." : "Book your assessment call."}</h1><p>{completed ? "Your call has been recorded as held. Review the adviser’s note and follow the next actions in this workspace." : "Choose a suitable time to discuss your written assessment, questions and recommended next steps with Migrz. Calls are capped at 60 minutes."}</p></header>{appointment ? <section className={`portal-appointment-status is-${appointment.status}`}><span>{completed ? "Call held · follow-up in progress" : ["confirmed", "rescheduled"].includes(appointment.status) ? "Confirmed appointment" : appointment.status === "requested" ? "Confirmation pending" : appointment.status.replaceAll("_", " ")}</span><h2>{callTime ? new Date(callTime).toLocaleString([], { dateStyle: "full", timeStyle: "short" }) : "Time being arranged"}</h2><p>{appointment.durationMinutes} minutes · {appointment.timezone}</p><dl><div><dt>Call reference</dt><dd>{appointment.publicId}</dd></div><div><dt>Status</dt><dd>{completed ? "Call completed" : appointment.status.replaceAll("_", " ")}</dd></div></dl>{completed ? <div className="portal-call-next"><strong>What happens now</strong><p>{appointment.adminNote || "Your Migrz adviser is preparing the written follow-up and any actions agreed during the call."}</p><button className="portal-primary" type="button" onClick={onViewNotifications}>Review next steps <Arrow /></button></div> : appointment.meetingUrl && ["confirmed", "rescheduled"].includes(appointment.status) ? <a className="portal-primary" href={appointment.meetingUrl} target="_blank" rel="noreferrer">{closeToCall ? "Join review call" : "View call details"} <Arrow /></a> : null}{!completed && appointment.rescheduleUrl && <a className="portal-secondary-link" href={appointment.rescheduleUrl} target="_blank" rel="noreferrer">Reschedule call</a>}{!completed && appointment.cancelUrl && <a className="portal-secondary-link" href={appointment.cancelUrl} target="_blank" rel="noreferrer">Cancel appointment</a>}{!completed && appointment.adminNote && <small>{appointment.adminNote}</small>}{appointment.status === "requested" && <button className="portal-link-button" onClick={() => setAppointment(null)}>Change requested time</button>}</section> : <form className="portal-appointment-form" onSubmit={requestAppointment}><div><span className="portal-eyebrow">{liveBooking ? "Live availability" : "Request a time"}</span><h2>{liveBooking ? "Choose an available 60-minute call." : "Choose your preferred call window."}</h2><p>{liveBooking ? "Your selection will be confirmed immediately and the Google Meet details will be kept in this portal." : "Migrz will confirm the final appointment by email and in this portal."}</p></div>{liveBooking && slots.length ? <div className="portal-live-slots" role="group" aria-label="Available review call times">{slots.slice(0, 16).map((slot) => <button type="button" className={requestedStart === slot ? "is-selected" : ""} key={slot} onClick={() => setRequestedStart(slot)}><strong>{new Date(slot).toLocaleDateString([], { weekday: "short", month: "short", day: "numeric" })}</strong><span>{new Date(slot).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</span></button>)}</div> : <label>Preferred date and time<input type="datetime-local" value={requestedStart} onChange={(event) => setRequestedStart(event.target.value)} required /></label>}{!liveBooking && <label>Call length<select value={duration} onChange={(event) => setDuration(Number(event.target.value))}><option value={30}>30 minutes</option><option value={45}>45 minutes</option><option value={60}>60 minutes</option></select><small>Calls cannot exceed one hour.</small></label>}<label className="portal-wide-field">What would you like to cover?<textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="Optional questions or topics for the Migrz team" maxLength={1000} /></label><div className="portal-appointment-zone"><span>Your timezone</span><strong>{timezone}</strong></div><footer><span role="status">{message}</span><button className="portal-primary" type="submit" disabled={busy || !requestedStart}>{busy ? "Confirming…" : liveBooking ? "Confirm this call" : "Request this call"} <Arrow /></button></footer></form>}</div>;
}

type StoredDocument = { id: string; fileName: string; contentType: string; size: number; status: string };
function Documents() {
  const [documents, setDocuments] = useState<StoredDocument[]>([]); const [message, setMessage] = useState("Loading documents…"); const [busy, setBusy] = useState(false);
  const load = async () => { const response = await fetch("/api/portal/documents", { cache: "no-store" }); const data = await response.json() as { documents?: StoredDocument[] }; if (response.ok) { setDocuments(data.documents || []); setMessage((data.documents || []).length ? "Documents are stored privately." : "No documents uploaded yet."); } else setMessage("Unable to load documents."); };
  // The initial private-document read resolves into this view's client state.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { void load(); }, []);
  const upload = async (file?: File) => { if (!file) return; setBusy(true); setMessage("Uploading securely…"); const form = new FormData(); form.append("file", file); const response = await fetch("/api/portal/documents", { method: "POST", body: form }); const data = await response.json() as { error?: string }; setBusy(false); if (!response.ok) return setMessage(data.error || "Unable to upload."); await load(); };
  const remove = async (id: string) => { setBusy(true); const response = await fetch(`/api/portal/documents?id=${encodeURIComponent(id)}`, { method: "DELETE" }); setBusy(false); if (response.ok) await load(); else setMessage("Unable to remove the document."); };
  return <div className="portal-subpage"><header><span className="portal-eyebrow">Documents</span><h1>Keep supporting evidence organised.</h1><p>Upload only documents relevant to the claims in your assessment. Files are private and limited to PDF, JPG or PNG up to 10 MB.</p></header><div className="portal-document-layout"><section className="portal-upload-zone"><span aria-hidden="true">↑</span><h2>Add a supporting document</h2><p>Files are stored in the private Migrz applicant vault and are never public.</p><label>{busy ? "Working…" : "Choose a file"}<input type="file" accept=".pdf,.jpg,.jpeg,.png" disabled={busy} onChange={(event) => void upload(event.target.files?.[0])} /></label></section><section className="portal-file-list"><span className="portal-eyebrow">Your documents</span><p aria-live="polite">{message}</p>{documents.map((file) => <div key={file.id}><span>DOC</span><a href={`/api/portal/documents/download?id=${encodeURIComponent(file.id)}`}><strong>{file.fileName}</strong></a><button disabled={busy} onClick={() => void remove(file.id)}>Remove</button></div>)}</section></div></div>;
}

function Payment() {
  return <div className="portal-subpage"><header><span className="portal-eyebrow">Payment</span><h1>Your assessment access is active.</h1><p>Your payment was verified before this workspace opened.</p></header><section className="portal-payment-lock"><span aria-hidden="true">✓</span><div><strong>Payment verified</strong><p>Your receipt remains with the payment provider. Migrz has unlocked this account for one professional pathway assessment.</p></div><button disabled>Paid</button></section></div>;
}

type ServiceMessage = { id: string; senderRole: "admin" | "applicant"; kind: string; subject: string; body: string; status: string; dueAt: number | null; resolvedAt: number | null; createdAt: number };
type PublishedReport = { id: string; version: number; fileName: string; size: number; summary: string; publishedAt: number };
function OperationsCenter({ initialTab, onNavigate }: { initialTab: "messages" | "report"; onNavigate: (view: View) => void }) {
  const [tab, setTab] = useState(initialTab); const [messages, setMessages] = useState<ServiceMessage[]>([]); const [report, setReport] = useState<PublishedReport | null>(null); const [application, setApplication] = useState<{ publicId: string; reviewStatus: string; reviewDueAt: number | null; casevaultStatus: string; casevaultReference: string | null; retentionUntil: number | null } | null>(null); const [body, setBody] = useState(""); const [busy, setBusy] = useState(false); const [message, setMessage] = useState("Loading your secure workspace…");
  const load = useCallback(async () => { const response = await fetch("/api/portal/operations", { cache: "no-store" }); const data = await response.json() as { application?: typeof application; messages?: ServiceMessage[]; report?: PublishedReport | null; error?: string }; if (!response.ok) return setMessage(data.error || "Unable to load updates."); setApplication(data.application || null); setMessages(data.messages || []); setReport(data.report || null); setMessage(""); }, []);
  // The initial private operations read resolves into this view's client state.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { void load(); }, [load]);
  const send = async (replyTo?: string) => { if (!body.trim()) return; setBusy(true); const response = await fetch("/api/portal/operations", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ body, replyTo, subject: replyTo ? "Information supplied" : "Question from applicant" }) }); const data = await response.json() as { error?: string }; setBusy(false); if (!response.ok) return setMessage(data.error || "Unable to send your message."); setBody(""); setMessage("Message sent securely to Migrz."); await load(); };
  const openRequest = [...messages].reverse().find((item) => item.kind === "information_request" && item.status === "open");
  // Download links intentionally request authenticated API responses.
  // eslint-disable-next-line @next/next/no-html-link-for-pages
  return <div className="portal-subpage portal-operations"><header><span className="portal-eyebrow">Submission {application?.publicId || "workspace"}</span><h1>{tab === "report" ? "Your written assessment." : "Private messages."}</h1><p>{tab === "report" ? "Download the latest published report and keep track of the transition into case operations." : "Ask questions, respond to information requests, and keep every decision tied to your assessment."}</p></header><div className="portal-operations-tabs"><button className={tab === "messages" ? "is-active" : ""} onClick={() => setTab("messages")}>Messages</button><button className={tab === "report" ? "is-active" : ""} onClick={() => setTab("report")}>Written report</button><a href="/api/portal/export">Download my data</a></div>{tab === "messages" ? <div className="portal-inbox-layout"><section className="portal-message-thread">{messages.length ? messages.map((item) => <article key={item.id} className={`is-${item.senderRole} is-${item.kind}`}><small>{item.senderRole === "admin" ? "Migrz team" : "You"} · {new Date(item.createdAt).toLocaleString([], { dateStyle: "medium", timeStyle: "short" })}</small><h2>{item.subject}</h2><p>{item.body}</p>{item.kind === "information_request" && <span>{item.status === "open" ? `Response requested${item.dueAt ? ` by ${new Date(item.dueAt).toLocaleDateString()}` : ""}` : "Response received"}</span>}</article>) : <div className="portal-empty-conversation"><strong>No messages yet.</strong><p>Use this space whenever you need the Migrz team to clarify an assessment or document request.</p></div>}</section><aside className="portal-compose"><span className="portal-eyebrow">{openRequest ? "Respond to request" : "New secure message"}</span><textarea value={body} onChange={(event) => setBody(event.target.value)} placeholder={openRequest ? "Provide the requested information and mention any new document you uploaded…" : "Write your question for the Migrz team…"} maxLength={5000} /><button className="portal-primary" disabled={busy || !body.trim()} onClick={() => void send(openRequest?.id)}>{busy ? "Sending…" : openRequest ? "Send response" : "Send message"} <Arrow /></button><small role="status">{message}</small></aside></div> : <section className="portal-report-card">{report ? <><div className="portal-report-icon">PDF</div><div><span>Published {new Date(report.publishedAt).toLocaleDateString()} · Version {report.version}</span><h2>{report.fileName}</h2><p>{report.summary || "Your professional pathway assessment is ready for secure download."}</p><a className="portal-primary" href={`/api/portal/report?id=${encodeURIComponent(report.id)}`}>Download written report <Arrow /></a></div></> : <><div className="portal-report-icon is-waiting">R</div><div><span>{application?.reviewStatus === "needs_information" ? "Action required" : "Professional review"}</span><h2>{application?.reviewStatus === "needs_information" ? "Migrz needs more information before completing the report." : "Your report is being prepared."}</h2><p>{application?.reviewDueAt ? `Current service target: ${new Date(application.reviewDueAt).toLocaleString([], { dateStyle: "full", timeStyle: "short" })}.` : "The publication date will appear here when the review is underway."}</p>{application?.reviewStatus === "needs_information" && <button className="portal-primary" onClick={() => { setTab("messages"); onNavigate("inbox"); }}>Respond to Migrz <Arrow /></button>}</div></>}<footer><strong>CaseVault handoff</strong><span>{application?.casevaultStatus === "handed_off" ? `Transferred · ${application.casevaultReference}` : "Begins only if you engage Migrz for full application support."}</span></footer></section>}</div>;
}

void AssessmentPreview; void DocumentsPreview; void PaymentPreview;

function Help() {
  return <div className="portal-subpage"><header><span className="portal-eyebrow">Help</span><h1>Questions should not stop your progress.</h1><p>Choose the kind of support you need. The live portal will connect these options to the Migrz assessment team.</p></header><div className="portal-help-grid"><article><span>01</span><h2>Assessment question</h2><p>Get clarity about information requested in the assessment.</p><button>Ask a question <Arrow /></button></article><article><span>02</span><h2>Document help</h2><p>Understand which evidence may support your professional record.</p><button>Request guidance <Arrow /></button></article><article><span>03</span><h2>Payment support</h2><p>Ask about assessment scope, checkout or payment confirmation.</p><button>Contact support <Arrow /></button></article></div></div>;
}
